-- Function: public.fn_get_child_consent_document_by_id
-- Backup generated on 2026-10-25 20:33:09

CREATE OR REPLACE FUNCTION public.fn_get_child_consent_document_by_id(p_tenant_id uuid, p_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, classroom_id uuid, child_id uuid, consent_template_id uuid, template_version character varying, document_version integer, document_title character varying, document_snapshot text, status character varying, signing_deadline timestamp with time zone, created_by uuid, created_at timestamp with time zone, admin_reviewed_by uuid, admin_reviewed_at timestamp with time zone, admin_review_notes text, approved_at timestamp with time zone, sent_at timestamp with time zone, signed_at timestamp with time zone, declined_at timestamp with time zone, withdrawn_at timestamp with time zone, signed_document_storage_key character varying, signed_document_checksum character varying, supersedes_document_id uuid, row_version integer, child_name text, branch_name character varying, classroom_name character varying)  LANGUAGE sql  STABLE AS $function$     SELECT          d.id, d.tenant_id, d.organization_id, d.branch_id, d.classroom_id, d.child_id,         d.consent_template_id, d.template_version, d.document_version, d.document_title,         d.document_snapshot, d.status, d.signing_deadline, d.created_by, d.created_at,         d.admin_reviewed_by, d.admin_reviewed_at, d.admin_review_notes, d.approved_at,         d.sent_at, d.signed_at, d.declined_at, d.withdrawn_at,         d.signed_document_storage_key, d.signed_document_checksum,         d.supersedes_document_id, d.row_version,         TRIM(CONCAT(c.first_name, ' ', c.last_name)) AS child_name,         b.name AS branch_name,         cl.name AS classroom_name     FROM child_consent_documents d     JOIN children c ON d.child_id = c.id     LEFT JOIN branches b ON d.branch_id = b.id     LEFT JOIN classrooms cl ON d.classroom_id = cl.id     WHERE d.tenant_id = p_tenant_id AND d.id = p_id; $function$ ;
